from taf.ul.ettf.logger import custom_logger, log
from taf.ul.ettf.typed.typed import typed
from taf.ul.ettf.typed.custom_types import ExistingFilepath
from taf.ul.ettf.utils.command import SudoCommand, CommandError
from taf.ul.ettf.utils.robot_handlers import with_callback_name
import os.path


WTS_DIR = '/opt/iphy'
RAMDISK = '/dev/shm'
WTS_RAMDISK = RAMDISK + '/iphy'
WTS_DIR_BACKUP = '/opt/iphy_bak'
MAX_RUNNING_TIME = 180.0


logger = custom_logger('WtsToRamdisk')


class WtsPerformance(object):

    @staticmethod
    @typed(source=ExistingFilepath())
    def _copy_folder_with_permissions(source, destination):
        return "cp -rp {} {}".format(source, destination)

    @staticmethod
    @typed(source=ExistingFilepath())
    def _rename_folder(source, destination):
        return "mv {} {}".format(source, destination)

    @staticmethod
    @typed(source=ExistingFilepath())
    def _create_symbolic_link(source, destination):
        return "ln -s {} {}".format(source, destination)

    @staticmethod
    def _remove_dir_or_file(destination):
        return "rm -rf {}".format(destination)

    def _copy_wts_to_ramdisk(self):
        self._run_command(self._copy_folder_with_permissions(WTS_DIR, RAMDISK))

    def _create_symlink_to_wts_on_ramdisk(self):
        self._run_command(self._create_symbolic_link(WTS_RAMDISK, WTS_DIR))

    def _delete_symlink_to_wts_on_ramdisk(self):
        self._run_command(self._remove_dir_or_file(WTS_DIR))

    def _backup_wts(self):
        self._run_command(self._rename_folder(WTS_DIR, WTS_DIR_BACKUP))

    def _restore_wts(self):
        self._run_command(self._rename_folder(WTS_DIR_BACKUP, WTS_DIR))

    def _cleanup_ramdisk(self):
        self._run_command(self._remove_dir_or_file(WTS_RAMDISK))

    @staticmethod
    def _backup_exists():
        return os.path.exists(WTS_DIR_BACKUP)

    @staticmethod
    def _run_command(command):
        cmd = SudoCommand(command)
        cmd.run(max_process_running_time=MAX_RUNNING_TIME)

    @log('Relocating WTS to ramdisk...', 'Relocating WTS to ramdisk finished', logger)
    def relocate_to_ramdisk(self):
        if self._backup_exists():
            logger.info('Wts is already relocated to ramdisk')
            return
        try:
            self._copy_wts_to_ramdisk()
            self._backup_wts()
            self._create_symlink_to_wts_on_ramdisk()
        except CommandError:
            logger.exception('Error raised during command execution')

    @with_callback_name('WTS Performance Teardown')
    def wts_performance_teardown(self):
        if not self._backup_exists():
            logger.info('There is no wts backup to relocate')
            return
        try:
            self._cleanup_ramdisk()
            self._delete_symlink_to_wts_on_ramdisk()
            self._restore_wts()
        except CommandError:
            logger.exception('Error raised during command execution')
